/** The test tree as the list GET .../behaviour sends; ids are the folder paths. */
export function testTree(): TreeNode[] {
  const positions = new Map<string | null, number>();
  return ROWS.map(([id, parentId, title]) => {
    const position = positions.get(parentId) ?? 0;
    positions.set(parentId, position + 1);
    return {
      id,
      parent_id: parentId,
      path: id,
      slug: null,
      position,
      level: id === "feature" ? 0 : id.split("/").length,
      title,
      summary: "",
      status: "answered",
      version: 1,
      open_questions: 0,
      default_answers: 0,
      needs_pass: false,
      same_as: null,
      handoff: null,
    };
  });
}
